-- H2 2.3.232;
;             
CREATE CACHED TABLE "PUBLIC"."COPIES"(
    "ACQUIRED_AT" DATE,
    "ID" BIGINT NOT NULL,
    "ITEM_ID" BIGINT NOT NULL,
    "RESERVED_BY" CHARACTER VARYING(255)
);      
ALTER TABLE "PUBLIC"."COPIES" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_76" PRIMARY KEY("ID");      
CREATE CACHED TABLE "PUBLIC"."ITEMS"(
    "DURATION" INTEGER NOT NULL,
    "MINIMUM_AGE" INTEGER,
    "RELEASED_AT" DATE,
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1 RESTART WITH 16) NOT NULL,
    "AUTHOR" CHARACTER VARYING(255),
    "IMAGE" CHARACTER VARYING(255),
    "TITLE" CHARACTER VARYING(255),
    "TYPE" CHARACTER VARYING(255)
); 
ALTER TABLE "PUBLIC"."ITEMS" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_4" PRIMARY KEY("ID");        
CREATE CACHED TABLE "PUBLIC"."LOANS"(
    "COPY_ID" BIGINT NOT NULL,
    "EXPIRED_AT" TIMESTAMP(6),
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "MEMBER_ID" BIGINT NOT NULL,
    "RETURNED_AT" TIMESTAMP(6),
    "STARTED_AT" TIMESTAMP(6)
);         
ALTER TABLE "PUBLIC"."LOANS" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_45" PRIMARY KEY("ID");       
-- 0 +/- SELECT COUNT(*) FROM PUBLIC.LOANS;   
CREATE CACHED TABLE "PUBLIC"."MEMBERS"(
    "BIRTH_DATE" DATE,
    "PREMIUM" BOOLEAN NOT NULL,
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1 RESTART WITH 11) NOT NULL,
    "CUENTA" CHARACTER VARYING(255),
    "EMAIL" CHARACTER VARYING(255),
    "PERFIL" CHARACTER VARYING(255),
    "USERNAME" CHARACTER VARYING(255)
);        
ALTER TABLE "PUBLIC"."MEMBERS" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_6" PRIMARY KEY("ID");      
ALTER TABLE "PUBLIC"."LOANS" ADD CONSTRAINT "PUBLIC"."FKLINSEUU52XB6WKNRXP9AE0UWU" FOREIGN KEY("COPY_ID") REFERENCES "PUBLIC"."COPIES"("ID") NOCHECK;         
ALTER TABLE "PUBLIC"."LOANS" ADD CONSTRAINT "PUBLIC"."FKCX90N1MINPB22V3JW4OJINQM" FOREIGN KEY("MEMBER_ID") REFERENCES "PUBLIC"."MEMBERS"("ID") NOCHECK;       
ALTER TABLE "PUBLIC"."COPIES" ADD CONSTRAINT "PUBLIC"."FKAQ8V2O6LM5D7CMQR05KUHC9P0" FOREIGN KEY("ITEM_ID") REFERENCES "PUBLIC"."ITEMS"("ID") NOCHECK;         
